int kvm_create_vcpu(struct kvm *kvm, u32 id) {
    int ret;
    struct kvm_vcpu *vcpu;

    if (kvm->online_vcpus >= KVM_MAX_VCPUS)
        return -EINVAL;

    vcpu = kvm_vcpu_create(kvm, id);
    if (!vcpu)
        return -ENOMEM;

    ret = kvm_vcpu_init(vcpu);
    if (ret < 0)
        goto fail_vcpu_init;

    ret = kvm_setup_preempt_notifier(vcpu);
    if (ret < 0)
        goto fail_preempt_notifier;

    if (kvm_vcpu_is_active(kvm, id)) {
        ret = -EEXIST;
        goto fail_vcpu_check;
    }

    ret = kvm_register_vcpu(kvm, vcpu);
    if (ret < 0)
        goto fail_register_vcpu;

    kvm->online_vcpus++;

    kvm_arch_post_vcpu_creation(vcpu);

    return 0;

fail_register_vcpu:
fail_vcpu_check:
    kvm_teardown_preempt_notifier(vcpu);
fail_preempt_notifier:
    kvm_vcpu_deinit(vcpu);
fail_vcpu_init:
    kvm_vcpu_free(vcpu);
    return ret;
}

int kvm_vcpu_create(struct kvm *kvm, u32 id)
{
    int r;

    if (id >= KVM_MAX_VCPUS)
        return -EINVAL;

    if (kvm->online_vcpus >= KVM_MAX_VCPUS)
        return -EINVAL;

    if (kvm->vcpus[id])
        return -EEXIST;

    kvm->vcpus[id] = kzalloc(sizeof(struct kvm_vcpu), GFP_KERNEL);
    if (!kvm->vcpus[id])
        return -ENOMEM;

    r = kvm_setup_vcpu(kvm, kvm->vcpus[id], id);
    if (r)
        goto fail_vcpu;

    r = kvm_init_vcpu(kvm->vcpus[id]);
    if (r)
        goto fail_notifier;

    r = kvm_arch_vcpu_create(kvm->vcpus[id]);
    if (r)
        goto fail_arch;

    kvm->online_vcpus++;
    return 0;

fail_arch:
    kvm_arch_vcpu_destroy(kvm->vcpus[id]);
fail_notifier:
    kvm_free_vcpu(kvm->vcpus[id]);
fail_vcpu:
    kfree(kvm->vcpus[id]);
    return r;
}

