int kvm_vcpu_create(struct kvm *kvm, u32 id)
{
	struct kvm_vcpu *vcpu;
	int ret;

	if (id >= KVM_MAX_VCPUS)
		return -EINVAL;

	if (kvm->online_vcpus >= KVM_MAX_VCPUS)
		return -ENOSPC;

	if (kvm->vcpus[id])
		return -EEXIST;

	vcpu = kmem_cache_zalloc(kvm_vcpu_cache, GFP_KERNEL);
	if (!vcpu)
		return -ENOMEM;

	kvm_vcpu_init(vcpu, kvm, id);
	vcpu->preempt_notifier = NULL;

	ret = kvm_vcpu_setup(vcpu);
	if (ret < 0)
		goto free_vcpu;

	vcpu->run = kzalloc(sizeof(*vcpu->run), GFP_KERNEL);
	if (!vcpu->run) {
		ret = -ENOMEM;
		goto free_vcpu;
	}

	kvm->vcpus[id] = vcpu;
	kvm->online_vcpus++;
	atomic_inc(&kvm->users_count);

	kvm_arch_vcpu_after_create(vcpu);

	return 0;

free_vcpu:
	kmem_cache_free(kvm_vcpu_cache, vcpu);
	return ret;
}

int kvm_vm_create_vcpu(struct kvm *kvm, u32 id)
{
    int r;
    struct kvm_vcpu *vcpu;

    if (id >= KVM_MAX_VCPUS)
        return -EINVAL;

    vcpu = kvm_vcpu_create(kvm, id);
    if (!vcpu)
        return -ENOMEM;

    r = kvm_setup_vcpu(vcpu);
    if (r < 0)
        goto free_vcpu;

    r = kvm_register_vcpu(vcpu);
    if (r < 0)
        goto free_vcpu;

    kvm->online_vcpus++;

    r = kvm_arch_post_vcpu_creation(vcpu);
    if (r < 0)
        goto unregister_vcpu;

    return 0;

unregister_vcpu:
    kvm_unregister_vcpu(vcpu);
free_vcpu:
    kvm_vcpu_free(vcpu);
    return r;
}
